 import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  root.name = config.id || 'pricing-card-1-label';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const timelines = [];

  const aspect = 512 / 320;
  const planeW = 1.0;
  const planeH = planeW / aspect;

  const planeGeo = new THREE.PlaneGeometry(planeW, planeH);
  const planeMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1.0,
    side: THREE.DoubleSide
  });
  const plane = new THREE.Mesh(planeGeo, planeMat);
  plane.name = 'orb-decor-plane';
  root.add(plane);

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.needsUpdate = true;
        planeMat.map = tex;
        planeMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  for (const item of items) {
    if (!item || !item.text) continue;
    const px = item.typography?.fontSize ?? 39;
    const worldSize = px * 0.005;

    const text = ctx.fontAtlas.createText(String(item.text), {
      fontSize: worldSize,
      color: colors.paper,
      align: 'left'
    });
    text.name = 'label-headline';
    text.position.set(planeW * 0.5 + 0.1, 0, 0.02);
    root.add(text);

    const accentGeo = new THREE.PlaneGeometry(worldSize * 0.85, worldSize * 0.06);
    const accentMat = new MeshBasicNodeMaterial({
      color: new THREE.Color(colors.accent),
      transparent: true,
      opacity: 0.9
    });
    const accent = new THREE.Mesh(accentGeo, accentMat);
    accent.name = 'accent-line';
    accent.position.set(planeW * 0.5 + 0.1, -worldSize * 0.75, 0.025);
    root.add(accent);

    break;
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((t) => {
      try { t?.kill(); } catch {}
    });
    root.traverse((obj) => {
      if (obj.geometry) {
        try { obj.geometry.dispose(); } catch {}
      }
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => {
            try {
              if (m.map) m.map.dispose();
              m.dispose();
            } catch {}
          });
        } else {
          try {
            if (obj.material.map) obj.material.map.dispose();
            obj.material.dispose();
          } catch {}
        }
      }
    });
  };

  return root;
}
